// Registers the service worker and subscribes the student to push notifications.
// Saves their FCM token to Supabase so the server can reach them.
// Returns: "granted" | "denied" | "unsupported"
async function subscribeToPush(studentId) {
  try {
    if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
      return "unsupported";
    }
    // Register service worker
    const reg = await navigator.serviceWorker.register("/sw.js", { scope: "/" });
    await navigator.serviceWorker.ready;

    // Request permission
    const permission = await Notification.requestPermission();
    if (permission !== "granted") return "denied";

    // Load Firebase dynamically so it doesn't bloat the initial bundle
    const [{ initializeApp, getApps }, { getMessaging, getToken }] = await Promise.all([
      import("https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js"),
      import("https://www.gstatic.com/firebasejs/10.7.1/firebase-messaging.js"),
    ]);
    const app = getApps().length ? getApps()[0] : initializeApp(FIREBASE_CONFIG);
    const messaging = getMessaging(app);

    // Get FCM token
    const token = await getToken(messaging, { vapidKey: VAPID_KEY, serviceWorkerRegistration: reg });
    if (!token) return "denied";

    // Save token to Supabase on the student record
    await db.update("students", `id=eq.${studentId}`, { push_token: token }).catch(() => {});

    // Subscribe to the shared topic via our API
    await fetch("/api/subscribe", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token }),
    }).catch(() => {});

    return "granted";
  } catch (e) {
    console.error("Push subscribe error:", e);
    return "unsupported";
  }
}

// Checks current notification permission state without prompting
function getNotificationPermission() {
  if (!("Notification" in window)) return "unsupported";
  return Notification.permission; // "default" | "granted" | "denied"
}

// ── Gemini Flash — fallback when Groq hits daily limit ───────────────────────
async function geminiCall(prompt, systemPrompt) {
  if (!GEMINI_KEY) throw new Error("GEMINI_KEY not configured");
  const full = systemPrompt ? systemPrompt + "\n\n" + prompt : prompt;
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${GEMINI_KEY}`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ contents: [{ parts: [{ text: full }] }], generationConfig: { maxOutputTokens: 1500, temperature: 0.3 } })
  });
  if (!res.ok) throw new Error("Gemini error: " + await res.text());
  const d = await res.json();
  return cleanText(d.candidates?.[0]?.content?.parts?.[0]?.text || "");
}

// ── Gemini Flash for feedback — higher quality, low temp, illegal-char retry ──
// Used by getQodFeedback. Pins to gemini-2.5-flash (free tier eligible) and uses
// temperature 0.2 for consistency. Retries once if output contains illegal scripts.
async function geminiCallForFeedback(prompt, systemPrompt, lang = "ko") {
  if (!GEMINI_KEY) throw new Error("GEMINI_KEY not configured");
  const callOnce = async (userPrompt) => {
    aiUsageTick("gemini25flash");
    const body = {
      contents: [{ role: "user", parts: [{ text: userPrompt }] }],
      generationConfig: { maxOutputTokens: lang === "zh" ? 1800 : 1500, temperature: 0.2 }
    };
    if (systemPrompt) {
      body.systemInstruction = { parts: [{ text: systemPrompt }] };
    }
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${GEMINI_KEY}`, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body)
    });
    if (!res.ok) throw new Error("Gemini feedback error: " + await res.text());
    const d = await res.json();
    return d.candidates?.[0]?.content?.parts?.[0]?.text || "";
  };
  let raw = await callOnce(prompt);
  // Retry once only if output contains truly illegal scripts (Japanese, Cyrillic, etc.)
  if (hasIllegalChars(raw, lang)) {
    const retryPrompt = prompt + (lang === "zh"
      ? "\n\nCRITICAL: Use ONLY Simplified Chinese (汉字) and English. No Korean, Japanese, Cyrillic."
      : "\n\nCRITICAL: Use ONLY Korean hangul (가-힣) and English (a-z A-Z). No Chinese characters, Japanese, Cyrillic, or any other scripts.");
    raw = await callOnce(retryPrompt);
  }
  return cleanText(raw, lang);
}

function isRateLimit(e) {
  const m = (e?.message || "").toLowerCase();
  return m.includes("429") || m.includes("rate limit") || m.includes("tpd") || m.includes("too many")
    || m.includes("audio_seconds") || m.includes("asr") || m.includes("limit exceeded");
}

// Logs rate limit hits to Supabase so Teacher Toms gets visibility on when limits are hit.
// Fire-and-forget — never throws, never blocks the UI.
async function logRateLimitError(context = "", studentName = "") {
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/error_logs`, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${SUPABASE_KEY}`,
        "Content-Type": "application/json",
        "Prefer": "return=minimal",
      },
      body: JSON.stringify({
        error_type: "rate_limit",
        context,
        student_name: studentName || "unknown",
        occurred_at: new Date().toISOString(),
      }),
    });
  } catch(_) {}
}
