// ── Avatar System ─────────────────────────────────────────────────────────────
// Two states only:
//   1. Custom photo — stored in students.profile_photo
//   2. Colored initial circle — derived from student name + id for consistent color

// Generates a consistent color from a string (name/id) — same student always
// gets the same color across sessions
const AVATAR_COLORS = [
  ["#1A3A6E", "#EEF2FF"], // navy on indigo
  ["#0F6E56", "#E1F5EE"], // teal on mint
  ["#853C1E", "#FEF3E8"], // rust on peach
  ["#6B21A8", "#F5F3FF"], // purple on lavender
  ["#1E5A8E", "#E6F1FB"], // blue on sky
  ["#854F0B", "#FAEEDA"], // amber on cream
  ["#991B1B", "#FEF2F2"], // red on pink
  ["#065F46", "#ECFDF5"], // emerald on green
];

const avatarColor = (student) => {
  const str = (student?.id || "") + (student?.name || "");
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
  return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
};

// ── StudentAvatar ─────────────────────────────────────────────────────────────
function StudentAvatar({ student, size = 38, style = {} }) {
  if (student?.profile_photo) {
    return (
      <div style={{ width: size, height: size, borderRadius: "50%", overflow: "hidden", flexShrink: 0, ...style }}>
        <img src={student.profile_photo} alt={student?.name || ""} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </div>
    );
  }
  const [fg, bg] = avatarColor(student);
  const initial = (student?.name || "?")[0].toUpperCase();
  const fontSize = Math.round(size * 0.38);
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", background: bg, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...style }}>
      <span style={{ fontSize, fontWeight: "700", color: fg, fontFamily: FONT, lineHeight: 1, userSelect: "none" }}>{initial}</span>
    </div>
  );
}

// ── AvatarPicker ──────────────────────────────────────────────────────────────
// Bottom sheet: photo upload (camera OR photo library), with initials preview as fallback.
// Two hidden file inputs:
//   - cameraRef: has capture="user" → opens front camera directly on mobile
//   - libraryRef: no capture attribute → opens device photo library (Photos app on iOS,
//                 Gallery on Android, file picker on desktop)
function AvatarPicker({ student, onClose, onSave }) {
  const lang = useLang();
  const [uploading, setUploading] = useState(false);
  const cameraRef = useRef(null);
  const libraryRef = useRef(null);

  const handlePhotoUpload = async (e) => {
    const file = e.target.files?.[0];
    // Reset input value so picking the same file twice in a row still fires onChange
    if (e.target) e.target.value = "";
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("Photo must be under 5MB"); return; }
    setUploading(true);
    try {
      const ext = (file.name.split(".").pop() || "jpg").toLowerCase();
      const fn = `avatar_${student.id}_${Date.now()}.${ext}`;
      const up = await fetch(`${SUPABASE_URL}/storage/v1/object/avatars/${fn}`, {
        method: "POST",
        headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${SUPABASE_KEY}`, "Content-Type": file.type || "image/jpeg" },
        body: file,
      });
      if (up.ok) {
        const url = `${SUPABASE_URL}/storage/v1/object/public/avatars/${fn}`;
        await db.update("students", `id=eq.${student.id}`, { profile_photo: url });
        onSave({ profile_photo: url });
        onClose();
      } else {
        alert("Upload failed — make sure the Supabase avatars bucket is set to public");
      }
    } catch(e) { alert("Upload error: " + e.message); }
    setUploading(false);
  };

  const handleRemovePhoto = async () => {
    try {
      await db.update("students", `id=eq.${student.id}`, { profile_photo: null });
      onSave({ profile_photo: null });
      onClose();
    } catch(e) { console.error("Remove photo error:", e); }
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", zIndex: 2000, display: "flex", alignItems: "flex-end", justifyContent: "center" }} onClick={onClose}>
      <div style={{ background: C.bg, borderRadius: "24px 24px 0 0", padding: "20px 24px 44px", width: "100%", maxWidth: "500px" }} onClick={e => e.stopPropagation()}>

        {/* Handle */}
        <div style={{ width: "36px", height: "4px", background: C.border, borderRadius: "100px", margin: "0 auto 20px" }} />

        {/* Preview */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "10px", marginBottom: "28px" }}>
          <StudentAvatar student={student} size={80} />
          <div style={{ fontSize: "16px", fontWeight: "700", color: C.text }}>{student?.name}</div>
          <div style={{ fontSize: "12px", color: C.textLight }}>
            {student?.profile_photo ? "Using your photo" : "Using initials — upload a photo to personalize"}
          </div>
        </div>

        {/* Hidden file inputs */}
        <input ref={cameraRef} type="file" accept="image/*" capture="user" style={{ display: "none" }} onChange={handlePhotoUpload} />
        <input ref={libraryRef} type="file" accept="image/*" style={{ display: "none" }} onChange={handlePhotoUpload} />

        {/* Take photo — opens camera */}
        <button onClick={() => cameraRef.current?.click()} disabled={uploading}
          style={{ width: "100%", padding: "15px", borderRadius: "100px", border: "none", background: C.navy, color: "#fff", fontSize: "15px", fontWeight: "800", cursor: uploading ? "default" : "pointer", fontFamily: FONT, marginBottom: "10px", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px" }}>
          {uploading
            ? React.createElement(React.Fragment, null, React.createElement(Spinner), React.createElement("span", { style: { marginLeft: "8px" } }, "Uploading…"))
            : "📷 Take a photo"}
        </button>

        {/* Choose from library — opens device photo library / gallery */}
        <button onClick={() => libraryRef.current?.click()} disabled={uploading}
          style={{ width: "100%", padding: "15px", borderRadius: "100px", border: `1px solid ${C.border}`, background: C.bg, color: C.text, fontSize: "15px", fontWeight: "700", cursor: uploading ? "default" : "pointer", fontFamily: FONT, marginBottom: "10px", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px" }}>
          🖼️ Choose from library
        </button>

        {/* Remove photo — only shown if they have one */}
        {student?.profile_photo && (
          <button onClick={handleRemovePhoto}
            style={{ width: "100%", padding: "12px", borderRadius: "100px", border: `1px solid ${C.border}`, background: "transparent", color: C.textMid, fontSize: "13px", fontWeight: "600", cursor: "pointer", fontFamily: FONT, marginBottom: "10px" }}>
            Remove photo
          </button>
        )}

        <button onClick={onClose}
          style={{ width: "100%", padding: "10px", background: "transparent", border: "none", color: C.textLight, fontSize: "13px", cursor: "pointer", fontFamily: FONT }}>
          Cancel
        </button>
      </div>
    </div>
  );
}
// Always use local date — toISOString() returns UTC which breaks date-based queries
// for users in UTC+ timezones (e.g. Korea UTC+9 is still "yesterday" in UTC until 9am)
const localToday = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
};
// QoD is now a weekly Thursday ritual, not a daily prompt — students didn't engage with
// it daily, and the daily goal is practice (phrases/Wavi), not answering a question. Gate
// the passive daily appearances (home Daily Focus row, Community tab) to Thursday only.
// getDay(): 0=Sun … 4=Thu. The opt-in Wavi "full" mode QoD is left untouched.
const isQodDay = (d = new Date()) => d.getDay() === 4;
// New grouped-card toolkit UI — now rolled out to all students. Kept as a function
// (rather than inlining `true`) so every call site stays untouched and the rollout can
// be narrowed again by restoring the per-student/name gate if ever needed.
const isNewUI = (u) => !!u;

// Redesign v3 rollout gate — per-student `redesign_v3_enabled` DB flag with the
// standard Toms-Lee/teacher name fallback so only the test account sees the new IA,
// tokens, Pretendard, tab bar, home, and session restyle until Toms rolls it out.
// Rollback for the entire redesign = flag off. Never default this to true.
const isRedesignV3 = (u) => !!(u && (u.redesign_v3_enabled || TEACHER_NAMES.includes(u.name)));
// Thankful Thursday — the weekly QoD is now a gratitude ritual: every Thursday all
// students share one thing they're thankful for. The prompt is auto-created so the
// experience runs without the teacher scheduling one (a teacher-scheduled Thursday
// prompt, if present, takes precedence). `db` is module-level (defined below; this
// declaration is only invoked at runtime, so referencing it here is fine).
const THANKFUL_THURSDAY_TAG = "Thankful Thursday";
const THANKFUL_THURSDAY_PROMPT = "What's one thing you're thankful for this week?";
// The current Thankful Thursday "week" is anchored to the most recent Thursday (today if it
// IS Thursday, else the Thursday earlier this week). getDay(): Thu=4.
const currentThankfulThursdayDate = (now = new Date()) => {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  d.setDate(d.getDate() - ((d.getDay() - 4 + 7) % 7));
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
};
// Open window (model #2): the current week's prompt is answerable ALL week, not just on
// Thursday. Returns/creates the prompt scheduled to the most recent Thursday on any day.
async function ensureThankfulThursdayPrompt() {
  const ttDate = currentThankfulThursdayDate();
  const existing = await db.get("qod_prompts", `scheduled_date=eq.${ttDate}&limit=1`).catch(() => []);
  if (existing[0]) return existing[0];
  try {
    const r = await db.insert("qod_prompts", { prompt: THANKFUL_THURSDAY_PROMPT, tag: THANKFUL_THURSDAY_TAG, spark: "Thankful Thursday", category: "weekly", difficulty: "easy", scheduled_date: ttDate });
    return Array.isArray(r) ? r[0] : r;
  } catch (e) { return { prompt: THANKFUL_THURSDAY_PROMPT, tag: THANKFUL_THURSDAY_TAG, id: "tt_" + ttDate, scheduled_date: ttDate }; }
}
// Returns ISO timestamps for start/end of the local calendar day in UTC
const localDayRange = () => {
  const d = new Date();
  const start = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0);
  const end   = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999);
  return { start: start.toISOString(), end: end.toISOString() };
};

// ── Active Time Tracker ──────────────────────────────────────────────────────
// Tracks how long a student is actually engaged with the app each day.
//
// Active = recent user interaction. Idle = 3+ minutes with no input.
// Backgrounded tabs pause immediately. Segments are saved to active_time_segments
// table in chunks (every 30s while active, plus on idle/exit) so data survives crashes.
//
// Wavi sessions report their own active time via reportWaviSession() — they're
// "always active" by nature (mic listening, audio playing) so we don't apply
// idle detection during a Wavi session.
const IDLE_THRESHOLD_MS = 3 * 60 * 1000; // 3 minutes
const FLUSH_INTERVAL_MS = 30 * 1000;     // save accumulated time every 30s

// Module-level flag: when true, the global "app" tracker pauses so Wavi sessions
// don't double-count (Wavi reports its own time on session end).
let waviSessionActive = false;
function setWaviSessionActive(active) { waviSessionActive = active; }

function useActivityTracker(user) {
  const lastActivityRef = React.useRef(Date.now());
  const accumulatedMsRef = React.useRef(0); // ms not yet flushed to DB
  const isActiveRef = React.useRef(true);
  const isBackgroundedRef = React.useRef(false);
  const lastTickRef = React.useRef(Date.now());

  React.useEffect(() => {
    if (!user?.id) return;

    const recordActivity = () => {
      lastActivityRef.current = Date.now();
      if (!isActiveRef.current && !isBackgroundedRef.current) {
        // Coming back from idle — reset tick so we don't credit idle time
        lastTickRef.current = Date.now();
        isActiveRef.current = true;
      }
    };

    const flushAccumulated = async (source = "app") => {
      const ms = accumulatedMsRef.current;
      accumulatedMsRef.current = 0;
      if (ms < 1000) return; // skip <1 second
      try {
        await db.insert("active_time_segments", {
          student_id: user.id,
          date: localToday(),
          seconds: Math.round(ms / 1000),
          source,
        });
      } catch(e) { console.warn("[activity] flush failed:", e?.message); }
    };

    // Tick every second to accumulate active time and detect idle
    const tickInterval = setInterval(() => {
      const now = Date.now();
      const sinceActivity = now - lastActivityRef.current;
      const sinceLastTick = now - lastTickRef.current;
      lastTickRef.current = now;

      // Skip if backgrounded or while Wavi owns the time accounting
      if (isBackgroundedRef.current || waviSessionActive) return;

      // Check for idle transition
      if (sinceActivity >= IDLE_THRESHOLD_MS) {
        if (isActiveRef.current) {
          // Just went idle — flush what we have, mark idle
          isActiveRef.current = false;
          flushAccumulated("app");
        }
        return; // don't accumulate while idle
      }

      // Active — accumulate. Cap the per-tick delta to handle browser throttling.
      const delta = Math.min(sinceLastTick, 2000);
      accumulatedMsRef.current += delta;
    }, 1000);

    // Periodic flush to DB so data survives crashes/closes
    const flushInterval = setInterval(() => flushAccumulated("app"), FLUSH_INTERVAL_MS);

    // Visibility — pause/resume on tab switch or app background
    const onVisibility = () => {
      if (document.hidden) {
        isBackgroundedRef.current = true;
        flushAccumulated("app");
      } else {
        isBackgroundedRef.current = false;
        lastTickRef.current = Date.now();
        lastActivityRef.current = Date.now();
        isActiveRef.current = true;
      }
    };

    // Activity events — anything counts as "still here"
    const activityEvents = ["pointerdown", "keydown", "scroll", "touchstart"];
    activityEvents.forEach(e => window.addEventListener(e, recordActivity, { passive: true }));
    document.addEventListener("visibilitychange", onVisibility);

    // Flush on page hide/unload — best effort. The 30s periodic flush above
    // covers most crash scenarios; this catches the last few seconds.
    const onUnload = () => { flushAccumulated("app"); };
    window.addEventListener("pagehide", onUnload);

    return () => {
      clearInterval(tickInterval);
      clearInterval(flushInterval);
      activityEvents.forEach(e => window.removeEventListener(e, recordActivity));
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("pagehide", onUnload);
      flushAccumulated("app");
    };
  }, [user?.id]);
}

// Report a completed Wavi session as a single active-time segment.
// Called by WavyScreen when finishSession runs. Wavi time is always "active"
// since the session involves continuous mic+audio interaction.
async function reportWaviSessionTime(userId, durationSeconds) {
  if (!userId || !durationSeconds || durationSeconds < 1) return;
  try {
    await db.insert("active_time_segments", {
      student_id: userId,
      date: localToday(),
      seconds: Math.round(durationSeconds),
      source: "wavi",
    });
  } catch(e) { console.warn("[activity] wavi report failed:", e?.message); }
}

// Fetch today's total active seconds for a student
async function getTodayActiveSeconds(userId) {
  if (!userId) return 0;
  try {
    const rows = await db.get("active_time_segments",
      `student_id=eq.${userId}&date=eq.${localToday()}&select=seconds`
    );
    return rows.reduce((sum, r) => sum + (r.seconds || 0), 0);
  } catch(e) { return 0; }
}

// Fetch this week's total active seconds per student (KST week, Mon-Sun)
async function getWeekActiveSecondsAllStudents() {
  try {
    const today = new Date();
    const dayOfWeek = today.getDay(); // 0 = Sun
    const daysFromMon = (dayOfWeek + 6) % 7;
    const monday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - daysFromMon);
    const mondayStr = `${monday.getFullYear()}-${String(monday.getMonth()+1).padStart(2,'0')}-${String(monday.getDate()).padStart(2,'0')}`;
    const rows = await db.get("active_time_segments",
      `date=gte.${mondayStr}&select=student_id,seconds`
    );
    const byStudent = {};
    rows.forEach(r => {
      byStudent[r.student_id] = (byStudent[r.student_id] || 0) + (r.seconds || 0);
    });
    return byStudent; // { studentId: totalSeconds }
  } catch(e) { return {}; }
}

// ── AI usage tracker ──────────────────────────────────────────────────────────
// Per-device daily request counter. Resets at local midnight.
// Buckets: groq70b, groq8b, gemini25flash, whisper.
// Limits below reflect published free-tier caps as of mid-2026 (Groq RPD: 1000/14400/2000;
// Gemini 2.5 Flash RPD: ~250 conservative). These are SAFE thresholds, not hard caps —
// going over just means the provider may return 429, and the next day will reset.
const AI_DAILY_LIMITS = {
  groq70b: 1000,        // Llama 3.3 70B Versatile — translation review, phrase generation, scaffold
  groq8b: 14400,        // Llama 3.1 8B Instant — Wavi evaluation (very high budget)
  gemini25flash: 250,   // Gemini 2.5 Flash — QoD feedback writer (conservative; Google publishes 250-1500)
  whisper: 2000,        // Whisper Large v3 — voice transcription
};
const AI_USAGE_KEY = "wayve_ai_usage_v1";
function aiUsageGetAll() {
  try {
    const raw = localStorage.getItem(AI_USAGE_KEY);
    if (!raw) return { date: localToday(), counts: {} };
    const parsed = JSON.parse(raw);
    if (parsed.date !== localToday()) return { date: localToday(), counts: {} };
    return parsed;
  } catch(e) { return { date: localToday(), counts: {} }; }
}
function aiUsageTick(bucket) {
  if (!AI_DAILY_LIMITS[bucket]) return;
  try {
    const cur = aiUsageGetAll();
    cur.counts[bucket] = (cur.counts[bucket] || 0) + 1;
    localStorage.setItem(AI_USAGE_KEY, JSON.stringify(cur));
    // Fire a window event so any mounted UI can refresh its display
    window.dispatchEvent(new CustomEvent("ai-usage-tick", { detail: { bucket } }));
  } catch(e) {}
}
function aiUsageGet(bucket) {
  return aiUsageGetAll().counts[bucket] || 0;
}
function aiUsageRemaining(bucket) {
  return Math.max(0, (AI_DAILY_LIMITS[bucket] || 0) - aiUsageGet(bucket));
}

// ── Supabase ──────────────────────────────────────────────────────────────────
const sb = async (path, opts = {}) => {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": opts.prefer || "return=representation", ...opts.headers },
    ...opts
  });
  if (!res.ok) { const err = await res.text(); throw new Error(err); }
  const text = await res.text();
  if (!text) return [];
  try { return JSON.parse(text); } catch(e) { return []; }
};
const db = {
  get: (t, q = "") => sb(`${t}?${q}`),
  insert: (t, d) => sb(t, { method: "POST", body: JSON.stringify(d) }),
  update: (t, q, d) => sb(`${t}?${q}`, { method: "PATCH", body: JSON.stringify(d) }),
  delete: (t, q) => sb(`${t}?${q}`, { method: "DELETE", prefer: "return=minimal" }),
  upsert: (t, d) => sb(t, { method: "POST", body: JSON.stringify(d), headers: { "Prefer": "resolution=merge-duplicates,return=representation" } }),
};

// Normalize "smart" quotes (curly apostrophes ' ' and curly double quotes " ") to ASCII
// equivalents. Auto-correct on macOS/iOS frequently substitutes them, which then breaks
// substring search and ilike dedup against entries stored with the other variant — silently
// creating duplicate phrase_bank rows. Used by phrase save/search paths in AddPhrasesTab.
const normalizeQuotes = (s) => (s || "")
  .replace(/[‘’]/g, "'")
  .replace(/[“”]/g, '"');

// ── Phrase queue scope ──────────────────────────────────────────────────────
// session_phrases holds both group phrases (group_id set, student_id null) and
// personal phrases (student_id set, group_id null). This builds the PostgREST
// filter for a student's queue: their group's phrases + their own personal ones.
// Returns a query fragment (without leading/trailing `&`) to splice into a
// session_phrases query. Falls back gracefully when group or student is missing.
function phraseScopeFilter(groupId, studentId) {
  if (groupId && studentId) return `or=(and(group_id.eq.${groupId},student_id.is.null),student_id.eq.${studentId})`;
  if (studentId) return `student_id=eq.${studentId}`;
  if (groupId) return `group_id=eq.${groupId}&student_id=is.null`;
  return "id=eq.00000000-0000-0000-0000-000000000000"; // matches nothing
}

// When a student joins/moves a group, make their phrases follow them and don't inherit the
// new group's back-catalog: (1) copy the OLD group's phrases into the student's personal
// list, (2) clean-slate (dismiss) the NEW group's existing phrases — so they start clean and
// only see phrases added to the new group AFTER they joined. Personal phrases already follow.
// Best-effort + idempotent (dedupes against existing personal phrases / dismissals).
async function migrateStudentPhrasesOnGroupChange(studentId, oldGroupId, newGroupId) {
  if (!studentId) return;
  try {
    if (oldGroupId) {
      const oldPhrases = await db.get("session_phrases", `group_id=eq.${oldGroupId}&student_id=is.null&select=phrase_id,in_library`).catch(() => []);
      const personal = await db.get("session_phrases", `student_id=eq.${studentId}&select=phrase_id`).catch(() => []);
      const have = new Set(personal.map(r => r.phrase_id));
      const toCopy = oldPhrases.filter(r => r.phrase_id && !have.has(r.phrase_id));
      if (toCopy.length) await db.insert("session_phrases", toCopy.map(r => ({ student_id: studentId, phrase_id: r.phrase_id, session_number: 1, in_library: !!r.in_library }))).catch(() => {});
    }
    if (newGroupId) {
      const newPhrases = await db.get("session_phrases", `group_id=eq.${newGroupId}&student_id=is.null&select=phrase_id`).catch(() => []);
      const personalNow = await db.get("session_phrases", `student_id=eq.${studentId}&select=phrase_id`).catch(() => []);
      const personalSet = new Set(personalNow.map(r => r.phrase_id));
      const dismissals = await db.get("phrase_dismissals", `student_id=eq.${studentId}&select=phrase_id`).catch(() => []);
      const dismissed = new Set(dismissals.map(r => r.phrase_id));
      // Don't dismiss phrases the student now owns personally (e.g. carried over and also in the new group).
      const toDismiss = newPhrases.filter(r => r.phrase_id && !dismissed.has(r.phrase_id) && !personalSet.has(r.phrase_id));
      if (toDismiss.length) await db.upsert("phrase_dismissals", toDismiss.map(r => ({ student_id: studentId, phrase_id: r.phrase_id }))).catch(() => {});
    }
  } catch(e) { console.warn("[group-change] phrase migration failed:", e?.message); }
}

// Fetch the set of phrase_ids this student has dismissed (small set; filtered
// client-side against fetched session_phrases). Returns a Set of phrase_bank ids.
async function fetchDismissedPhraseIds(studentId) {
  if (!studentId) return new Set();
  const rows = await db.get("phrase_dismissals", `student_id=eq.${studentId}&select=phrase_id`).catch(() => []);
  return new Set(rows.map(r => r.phrase_id).filter(Boolean));
}

// ── Session-notes audio upload ─────────────────────────────────────────────
// Same pattern as the QoD teacher comment upload (line ~19795): POST to the
// public storage bucket, fall back to an inline data-URL if upload fails so the
// note still saves rather than silently losing the recording.
async function uploadSessionNoteAudio(blob, label, folder) {
  const mime = blob.type || "audio/webm";
  const ext = mime.includes("mp4") ? "mp4" : mime.includes("ogg") ? "ogg" : "webm";
  const safeLabel = String(label || "x").replace(/[^a-z0-9-]/gi, "").slice(0, 12) || "x";
  // Optional folder prefix (e.g. "student-notes/{student_id}") so the two note
  // features keep separate paths in the shared bucket. Falls back to flat naming.
  const safeFolder = folder ? String(folder).replace(/[^a-z0-9/_-]/gi, "") : "";
  const base = `note_${safeLabel}_${Date.now()}.${ext}`;
  const fn = safeFolder ? `${safeFolder}/${base}` : base;
  try {
    const up = await fetch(`${SUPABASE_URL}/storage/v1/object/session-notes-audio/${fn}`, {
      method: "POST",
      headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}`, "Content-Type": mime.split(";")[0] },
      body: blob,
    });
    if (up.ok) return `${SUPABASE_URL}/storage/v1/object/public/session-notes-audio/${fn}`;
  } catch(e) { /* fall through to base64 */ }
  return await new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result);
    r.onerror = rej;
    r.readAsDataURL(blob);
  });
}

// Resolve the (single, for now) teacher account so student → teacher feedback can
// be addressed with a real teacher_id. Cached for the session. Multi-teacher
// assignment is intentionally out of scope; this returns the first teacher account.
let _teacherAccountCache = null;
async function resolveTeacherAccount() {
  if (_teacherAccountCache) return _teacherAccountCache;
  try {
    const list = TEACHER_NAMES.map(n => `"${encodeURIComponent(n)}"`).join(",");
    const rows = await db.get("students", `name=in.(${list})&select=id,name&limit=1`).catch(() => []);
    if (rows && rows[0]) { _teacherAccountCache = rows[0]; return rows[0]; }
  } catch(e) {}
  // Fallback: a stable string id so the NOT NULL column is always populated.
  return { id: "teacher", name: TEACHER_DISPLAY_NAME };
}

