// ── Phrase tags helpers ───────────────────────────────────────────────────────
// Multi-tag support. phrase_tags is a junction table (phrase_id, tag_id).
// We cache tags per phrase_id as a Map: { phraseId → [tagId, ...] }
// Loaded on-demand, refreshed when tags are written.
let phraseTagsCache = new Map(); // phraseId → tagId[]

async function loadPhraseTags(phraseIds) {
  if (!phraseIds || phraseIds.length === 0) return;
  try {
    const ids = phraseIds.filter(id => id && !phraseTagsCache.has(id));
    if (ids.length === 0) return;
    // Batch fetch all tags for these phrases
    const rows = await db.get("phrase_tags", `phrase_id=in.(${ids.map(id => `"${id}"`).join(",")})&select=phrase_id,tag_id`).catch(() => []);
    // Seed empty arrays for all requested ids (so we know we tried)
    ids.forEach(id => { if (!phraseTagsCache.has(id)) phraseTagsCache.set(id, []); });
    rows.forEach(r => {
      const existing = phraseTagsCache.get(r.phrase_id) || [];
      if (!existing.includes(r.tag_id)) existing.push(r.tag_id);
      phraseTagsCache.set(r.phrase_id, existing);
    });
  } catch(e) { /* non-fatal */ }
}

function getPhraseTags(phraseId) {
  return phraseTagsCache.get(phraseId) || [];
}

async function setPhraseTagsFor(phraseId, tagIds) {
  if (!phraseId) return;
  try {
    // Delete all existing tags for this phrase, then insert new ones
    await db.delete("phrase_tags", `phrase_id=eq.${phraseId}`);
    for (const tagId of tagIds) {
      await db.insert("phrase_tags", { phrase_id: phraseId, tag_id: tagId }).catch(() => {});
    }
    phraseTagsCache.set(phraseId, [...tagIds]);
    // Also update phrase_bank.tag with the first tag for backward compatibility
    const primaryTag = tagIds[0] || null;
    await db.update("phrase_bank", `id=eq.${phraseId}`, { tag: primaryTag }).catch(() => {});
  } catch(e) { console.warn("[phrase_tags] write error:", e?.message); }
}
const lastActiveDisplay = (student) => {
  if (student.last_seen) {
    const d = new Date(student.last_seen);
    const now = new Date();
    const diffMs = now - d;
    const diffMins = Math.floor(diffMs / 60000);
    const isToday = d.toDateString() === now.toDateString();
    const timeStr = d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    if (diffMins < 2) return "Active now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (isToday) return `Today ${timeStr}`;
    const yesterday = new Date(now); yesterday.setDate(yesterday.getDate() - 1);
    if (d.toDateString() === yesterday.toDateString()) return `Yesterday ${timeStr}`;
    return d.toLocaleDateString([], { month: "short", day: "numeric" }) + " " + timeStr;
  }
  if (student.last_practice) {
    const today = new Date().toISOString().slice(0, 10);
    const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
    if (student.last_practice === today) return "Today";
    if (student.last_practice === yesterday) return "Yesterday";
    return student.last_practice;
  }
  return null;
};

const streakDisplay = (streak) => {
  const n = streak || 0;
  if (n === 0) return null;               // blank — not started
  if (n < 3)  return `${n} streak`;       // number only — building up
  return `🔥 ${n} streak`;               // earned
};
const streakShort = (streak) => {
  const n = streak || 0;
  if (n === 0) return null;
  if (n < 3)  return `${n}`;
  return `🔥 ${n}`;
};

