// ── Haptic feedback — uses Web Vibration API (iOS Safari 16+, all Android) ────
// Call on meaningful interactions: save, submit, tab switch. Patterns match
// Apple's Taptic Engine feel: light (selection), medium (impact), success (notif).
const haptic = {
  light:   () => { try { navigator.vibrate?.(6);  } catch(_) {} },
  medium:  () => { try { navigator.vibrate?.(12); } catch(_) {} },
  success: () => { try { navigator.vibrate?.([8, 50, 12]); } catch(_) {} },
};
// ── Helpers ───────────────────────────────────────────────────────────────────
// Strips everything that isn't Korean hangul, English/Latin, numbers, punctuation, or emoji
const cleanText = (t, lang = "ko") => {
  if (!t) return t;
  return t.split("").filter(c => {
    const code = c.charCodeAt(0);
    const isKorean = (code >= 0xAC00 && code <= 0xD7A3) || (code >= 0x1100 && code <= 0x11FF) || (code >= 0x3130 && code <= 0x318F);
    const isChinese = (code >= 0x4E00 && code <= 0x9FFF) || (code >= 0x3400 && code <= 0x4DBF) ||
                      (code >= 0x3000 && code <= 0x303F) || // CJK punctuation （。，、：；！？""''…—）
                      (code >= 0xFF00 && code <= 0xFFEF) || // Fullwidth forms
                      (code >= 0x2018 && code <= 0x201F);   // Smart quotes used in Chinese
    const isLatin = code >= 0x0020 && code <= 0x007E;
    const isEmoji = (code >= 0x1F300 && code <= 0x1FAFF) || (code >= 0x2600 && code <= 0x27BF) || (code >= 0xFE00 && code <= 0xFE0F) || (code >= 0x1F900 && code <= 0x1F9FF);
    const isNewline = c === "\n";
    // Block: Hiragana, Katakana, Cyrillic, Arabic (always illegal)
    const isAlwaysIllegal = (code >= 0x3040 && code <= 0x309F) || (code >= 0x30A0 && code <= 0x30FF) ||
                            (code >= 0x0400 && code <= 0x04FF) || (code >= 0x0600 && code <= 0x06FF);
    if (isAlwaysIllegal) return false;
    if (lang === "zh") return (isChinese || isLatin || isEmoji || isNewline);
    return (isKorean || isLatin || isEmoji || isNewline) && !isChinese;
  }).join("");
};

// Detects truly illegal characters (Japanese, Cyrillic, Arabic — never Korean or Chinese)
const hasIllegalChars = (t, lang = "ko") => {
  if (!t) return false;
  return t.split("").some(c => {
    const code = c.charCodeAt(0);
    // Always illegal: Hiragana, Katakana, Cyrillic, Arabic
    const alwaysIllegal = (code >= 0x3040 && code <= 0x309F) || (code >= 0x30A0 && code <= 0x30FF) ||
                          (code >= 0x0400 && code <= 0x04FF) || (code >= 0x0600 && code <= 0x06FF);
    if (alwaysIllegal) return true;
    // For Korean mode: Chinese chars are illegal
    if (lang !== "zh") {
      return (code >= 0x4E00 && code <= 0x9FFF) || (code >= 0x3400 && code <= 0x4DBF);
    }
    // For Chinese mode: Korean hangul is illegal
    if (lang === "zh") {
      return (code >= 0xAC00 && code <= 0xD7A3) || (code >= 0x1100 && code <= 0x11FF) || (code >= 0x3130 && code <= 0x318F);
    }
    return false;
  });
};

// Cleans all string values in a parsed JSON object recursively
const cleanParsedObject = obj => {
  if (!obj) return obj;
  if (typeof obj === "string") return cleanText(obj);
  if (Array.isArray(obj)) return obj.map(cleanParsedObject);
  if (typeof obj === "object") {
    const out = {};
    for (const k in obj) out[k] = typeof obj[k] === "string" ? cleanText(obj[k]) : cleanParsedObject(obj[k]);
    return out;
  }
  return obj;
};

// groqCall wrapper that auto-retries once if output contains illegal characters
const groqCallSafe = async (prompt, retryPrompt, lang = "ko") => {
  const result = await groqCall(prompt);
  if (hasIllegalChars(result, lang)) {
    const retried = await groqCall(retryPrompt || prompt + (lang === "zh"
      ? "\n\nCRITICAL: Use ONLY Simplified Chinese (汉字) and English. No Korean, Japanese, Cyrillic."
      : "\n\nCRITICAL: Use ONLY Korean hangul (가-힣) and English (a-z A-Z). No Chinese, Japanese, Cyrillic, or any other scripts."));
    return retried;
  }
  return result;
};

// ── Feedback Display — rich formatted output ──────────────────────────────────
function FeedbackDisplay({ text }) {
  const lang = useLang();
  try {
    if (!text || typeof text !== "string") return null;
    const lines = text.split("\n").map(l => l.trim()).filter(Boolean);
    if (lines.length === 0) return null;

    const isScore = l => l.startsWith("🎯");
    const isWrong = l => l.startsWith("❌");
    const isExplain = l => l.startsWith("📌");
    const isAlt = l => l.startsWith("->");
    const isMotivation = l => l.startsWith("💪");

    const elements = lines.map((line, i) => {
      try {
        if (isScore(line) || /^(?:🎯\s*)?(?:점수|分数|Score)\s*:/.test(line) || /^\s*:\s*\d+\/10/.test(line)) {
          const scoreMatch = line.match(/(\d+)\/10/);
          if (!scoreMatch) return null;
          const score = parseInt(scoreMatch[1]);
          const color = score >= 8 ? C.success : score >= 6 ? C.gold : C.retry;
          return React.createElement("div", { key: i, style: { display: "inline-flex", alignItems: "center", gap: "6px", background: color + "18", border: `1px solid ${color}40`, borderRadius: "8px", padding: "4px 10px", fontSize: "13px", fontWeight: "700", color } },
            "🎯 ", lang === "zh" ? `分数: ${score}/10` : `점수: ${score}/10`);
        }
        if (line === "✅ 잘한 점" || line === "✅ 잘한점" || line === "잘한 점" || line === "✅ 做得好" || line === "✅ 优点" || line === "做得好")
          return React.createElement("div", { key: i, style: { fontSize: "13px", fontWeight: "700", color: C.success, textTransform: "uppercase", letterSpacing: "0.5px", marginTop: "4px" } }, lang === "zh" ? "✅ 做得好" : "✅ 잘한 점");
        if (line === "📝 문법 피드백" || line === "📝 문법피드백" || line === "문법 피드백" || line === "📝 语法反馈" || line === "📝 语法" || line === "语法反馈")
          return React.createElement("div", { key: i, style: { fontSize: "13px", fontWeight: "700", color: C.error, textTransform: "uppercase", letterSpacing: "0.5px", marginTop: "4px" } }, lang === "zh" ? "📝 语法反馈" : "📝 문법 피드백");
        if (line === "💡 이렇게도 말할 수 있어요" || line === "이렇게도 말할 수 있어요" || line === "💡 더 자연스럽게" || line === "더 자연스럽게" || line === "💡 更自然的说法" || line === "💡 可以这样说" || line === "更自然的说法")
          return React.createElement("div", { key: i, style: { fontSize: "13px", fontWeight: "700", color: C.gold, textTransform: "uppercase", letterSpacing: "0.5px", marginTop: "4px" } }, lang === "zh" ? "💡 更自然的说法" : "💡 더 자연스럽게");
        if (line === "완벽해요!" || line === "완벽해요" || line === "完美！" || line === "完美")
          return React.createElement("div", { key: i, style: { background: C.successBg, border: `1px solid #A8D5B5`, borderRadius: "6px", padding: "8px 12px", fontSize: "14px", color: C.success, fontWeight: "600" } }, lang === "zh" ? "✨ 完美！" : "✨ 완벽해요!");
        if (isWrong(line))
          return React.createElement("div", { key: i, style: { background: C.errorBg, borderRadius: "6px", padding: "8px 12px", fontSize: "14px", color: C.error, fontFamily: "monospace" } },
            "❌ ", React.createElement("span", { style: { fontWeight: "700" } }, line.replace("❌", "").trim()));
        // ✅ correction line — only highlight if it follows an ❌ line
        if (line.startsWith("✅") && i > 0) {
          const prevLine = i >= 1 ? lines[i-1] : null;
          const prev2Line = i >= 2 ? lines[i-2] : null;
          const wrongLine = (prevLine && prevLine.startsWith("❌")) ? prevLine : (prev2Line && prev2Line.startsWith("❌")) ? prev2Line : null;
          if (wrongLine) {
            const wrongWords = new Set((wrongLine.replace("❌", "").trim().toLowerCase().replace(/[^a-z0-9\s]/g, "") || "").split(" ").filter(Boolean));
            const correctText = line.replace("✅", "").trim();
            const correctWords = correctText.split(" ");
            return React.createElement("div", { key: i, style: { background: C.successBg, borderRadius: "6px", padding: "8px 12px", fontSize: "14px", color: C.success, fontFamily: "monospace" } },
              "✅ ",
              ...correctWords.map((word, wi) => {
                const clean = word.toLowerCase().replace(/[^a-z0-9]/g, "");
                const isNew = clean && !wrongWords.has(clean);
                return [
                  React.createElement("span", { key: wi, style: { fontWeight: isNew ? "900" : "400", textDecoration: isNew ? "underline" : "none" } }, word),
                  wi < correctWords.length - 1 ? React.createElement("span", { key: wi + "-sp", style: { textDecoration: "none" } }, " ") : null
                ];
              })
            );
          }
        }
        if (isExplain(line))
          return React.createElement("div", { key: i, style: { background: C.goldBg, borderLeft: `3px solid ${C.gold}`, borderRadius: "0 6px 6px 0", padding: "8px 12px", fontSize: "13px", color: C.textMid } }, line.replace("📌", "").trim());
        if (isAlt(line))
          return React.createElement("div", { key: i, style: { background: C.bgSoft, borderRadius: "6px", padding: "8px 12px", fontSize: "14px", color: C.text, fontStyle: "italic" } }, line);
        if (isMotivation(line))
          return React.createElement("div", { key: i, style: { marginTop: "4px", fontSize: "14px", color: C.textMid, fontWeight: "500", textAlign: "center" } }, line.replace("💪", "").trim() + " 💪");
        return React.createElement("div", { key: i, style: { fontSize: "14px", color: C.text, lineHeight: 1.7 } }, line);
      } catch(_) {
        return React.createElement("div", { key: i, style: { fontSize: "14px", color: C.text, lineHeight: 1.7 } }, line);
      }
    }).filter(Boolean);

    return React.createElement("div", { style: { display: "flex", flexDirection: "column", gap: "10px" } }, ...elements);
  } catch(_) {
    return React.createElement("div", { style: { fontSize: "14px", color: C.text, padding: "8px" } }, text);
  }
}

function highlightMissed(target, spoken) {
  if (!target || !spoken) return React.createElement("span", null, target);
  const norm = s => s.toLowerCase().replace(/[^a-z0-9\s]/g, "").trim();
  const spokenNorm = norm(spoken);
  return React.createElement("span", null,
    target.split(" ").map((word, i, arr) => [
      React.createElement("span", { key: i, style: { color: spokenNorm.includes(norm(word)) ? C.text : C.error, textDecoration: spokenNorm.includes(norm(word)) ? "none" : "underline", fontWeight: spokenNorm.includes(norm(word)) ? "400" : "600" } }, word),
      i < arr.length - 1 ? React.createElement("span", { key: i + "-sp", style: { textDecoration: "none" } }, " ") : null
    ])
  );
}

// ── TTS — ElevenLabs voices ────────────────────────────────────────────────────
const ELEVEN_KEY = process.env.REACT_APP_ELEVEN_KEY;
const ELEVEN_VOICE_ID    = "nzFihrBIvB34imQBuxub"; // English voice (phrases)
const ELEVEN_VOICE_ID_KO = "prgs92xTdxeczorJi7ez"; // Jay — Korean voiceover
let currentAudio = null;
let globalPlaybackSpeed = 1.0;

const ttsCache = new Map();

// ── Phrase token replacement ─────────────────────────────────────────────────
const PHRASE_TOKENS = {
  "{{name}}":    (user, group) => user?.name || "___",
  "{{hometown}}": (user) => user?.hometown || "___",
  "{{job}}":     (user) => user?.job || "___",
  "{{hobby}}":   (user) => user?.hobby || "___",
  "{{teacher}}": (user, group) => getTeacherName(group),
  "{{country}}": () => "South Korea",
  "{{today}}":   () => new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }),
  "{{day}}":     () => new Date().toLocaleDateString("en-US", { weekday: "long" }),
  "{{month}}":   () => new Date().toLocaleDateString("en-US", { month: "long" }),
};

let _tokenUser = null;
let _tokenGroup = null;

function applyPhraseTokens(text, user, group) {
  if (!text) return text;
  const u = user || _tokenUser;
  const g = group || _tokenGroup;
  let result = text;
  Object.entries(PHRASE_TOKENS).forEach(([token, fn]) => {
    if (result.includes(token)) result = result.replaceAll(token, fn(u, g));
  });
  return result;
}

// ── Pronunciation fixes ───────────────────────────────────────────────────────
const pronunciationFixes = new Map();
async function loadPronunciationFixes() {
  try {
    const fixes = await db.get("pronunciation_fixes", "order=word.asc").catch(() => []);
    pronunciationFixes.clear();
    fixes.forEach(f => { if (f.word && f.phonetic) pronunciationFixes.set(f.word.toLowerCase().trim(), f.phonetic.trim()); });
  } catch(e) {}
}


// ── Speaking state pub/sub ────────────────────────────────────────────────────
// Tracks which text+speed combo is currently loading or playing, so any listen
// button across the app can show a visual indicator without prop drilling.
// State shape: { text, speed, status: 'idle' | 'loading' | 'playing' }
// Speed is part of the key because the same phrase may have a normal-speed
// button and a slow-speed button — they should show state independently.
const speakingState = { text: null, speed: null, status: "idle" };
const speakingSubscribers = new Set();
function notifySpeaking() {
  speakingSubscribers.forEach(fn => { try { fn(); } catch(e) {} });
}
function setSpeakingState(text, status, speed = null) {
  speakingState.text = text;
  speakingState.speed = speed;
  speakingState.status = status;
  notifySpeaking();
}

// React hook: returns { isLoading, isPlaying } for a given text.
// By default matches any speed for this text (the common case — one main listen
// button per text). When `exactSpeed` is true, only matches the given speed
// (use for buttons that visually distinguish by speed, like "🐢 천천히" buttons
// alongside a regular "🔊 듣기" button on the same row).
function useSpeakingState(text, speed = null, exactSpeed = false) {
  const [, force] = useState(0);
  useEffect(() => {
    const cb = () => force(n => n + 1);
    speakingSubscribers.add(cb);
    return () => { speakingSubscribers.delete(cb); };
  }, []);
  const targetKey = (text || "").trim();
  const activeKey = (speakingState.text || "").trim();
  const speedMatch = exactSpeed ? (speakingState.speed || null) === speed : true;
  const isMatch = targetKey && targetKey === activeKey && speedMatch;
  return {
    isLoading: isMatch && speakingState.status === "loading",
    isPlaying: isMatch && speakingState.status === "playing",
    isActive: isMatch && speakingState.status !== "idle",
  };
}

async function speak(text, speed = null) {
  if (currentAudio) { currentAudio.pause(); currentAudio = null; }
  const playSpeed = speed !== null ? speed : globalPlaybackSpeed;
  const cacheKey = text.trim();
  // Apply pronunciation fixes — replace each word if a fix exists
  const fixedText = text.trim().split(/\s+/).map(word => {
    const clean = word.toLowerCase().replace(/[^a-z0-9']/g, "");
    return pronunciationFixes.has(clean) ? pronunciationFixes.get(clean) : word;
  }).join(" ");
  const ttsText = fixedText;

  // Set initial state — cached audio goes straight to "playing", uncached starts as "loading"
  const isCached = ttsCache.has(cacheKey);
  setSpeakingState(text, isCached ? "playing" : "loading", speed);

  if (isCached) {
    try {
      currentAudio = new Audio(ttsCache.get(cacheKey));
      currentAudio.playbackRate = playSpeed;
      currentAudio.playsInline = true;
      currentAudio.onended = () => { setSpeakingState(null, "idle"); currentAudio = null; };
      currentAudio.onerror = () => { setSpeakingState(null, "idle"); currentAudio = null; };
      await currentAudio.play();
      return;
    } catch(e) {
      // Cache URL may have expired, fall through to re-fetch
      ttsCache.delete(cacheKey);
      setSpeakingState(text, "loading", speed);
    }
  }

  try {
    const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${ELEVEN_VOICE_ID}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "xi-api-key": ELEVEN_KEY },
      body: JSON.stringify({
        text: ttsText,
        model_id: "eleven_turbo_v2_5",
        voice_settings: { stability: 0.3, similarity_boost: 0.75, style: 0.6, use_speaker_boost: true },
      })
    });
    if (!res.ok) throw new Error("ElevenLabs TTS failed: " + await res.text());
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    ttsCache.set(text.trim(), url);
    const audio = new Audio();
    audio.src = url;
    audio.playbackRate = playSpeed;
    audio.playsInline = true;
    currentAudio = audio;
    audio.onplay = () => setSpeakingState(text, "playing", speed);
    audio.onended = () => { URL.revokeObjectURL(url); currentAudio = null; setSpeakingState(null, "idle"); };
    audio.onerror = () => { URL.revokeObjectURL(url); currentAudio = null; setSpeakingState(null, "idle"); };
    await audio.play();
  } catch(e) {
    console.warn("ElevenLabs TTS failed, falling back to Groq:", e.message);
    try {
      const res = await fetch("https://api.groq.com/openai/v1/audio/speech", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${GROQ_KEY}` },
        body: JSON.stringify({ model: "playai-tts", input: text, voice: "Calum-PlayAI", response_format: "mp3" })
      });
      if (!res.ok) throw new Error();
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const audio = new Audio(url);
      audio.playbackRate = playSpeed;
      currentAudio = audio;
      audio.onplay = () => setSpeakingState(text, "playing", speed);
      audio.onended = () => { URL.revokeObjectURL(url); currentAudio = null; setSpeakingState(null, "idle"); };
      audio.onerror = () => { URL.revokeObjectURL(url); currentAudio = null; setSpeakingState(null, "idle"); };
      await audio.play();
    } catch(e2) {
      try {
        window.speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(text);
        u.lang = "en-US";
        u.rate = 0.85 * playSpeed;
        u.onstart = () => setSpeakingState(text, "playing", speed);
        u.onend = () => setSpeakingState(null, "idle");
        u.onerror = () => setSpeakingState(null, "idle");
        window.speechSynthesis.speak(u);
      } catch(e3) {
        setSpeakingState(null, "idle");
      }
    }
  }
}

// ── ListenIcon ───────────────────────────────────────────────────────────────
// Renders the icon for a listen button. Idle = static icon. Loading = same
// icon, dimmed (signals "something is happening" without changing identity).
// Playing = icon pulses gently. The pulse subtly grows and fades, mirroring
// audio waves — without being noisy.
function ListenIcon({ text, speed = null, exactSpeed = false, fallback = "🔊" }) {
  const { isLoading, isPlaying } = useSpeakingState(text, speed, exactSpeed);
  if (isLoading) return React.createElement("span", {
    style: { display: "inline-block", opacity: 0.45, transition: "all 0.15s" }
  }, fallback);
  if (isPlaying) return React.createElement("span", {
    style: { display: "inline-block", animation: "speakerPulse 0.9s ease-in-out infinite" }
  }, fallback);
  return fallback;
}

