// ── Student Screen ────────────────────────────────────────────────────────────

// ── Modal Portal — renders directly into document.body, bypassing all CSS transforms ──
function ModalPortal({ children }) {
  const el = useRef(document.createElement("div"));
  useEffect(() => {
    const portal = el.current;
    portal.style.cssText = "position:fixed;top:0;left:0;width:100%;height:100%;z-index:9999;pointer-events:none;";
    document.body.appendChild(portal);
    return () => { document.body.removeChild(portal); };
  }, []);
  return ReactDOM.createPortal(
    React.createElement("div", { style: { pointerEvents: "all" } }, children),
    el.current
  );
}

// ── Error Boundary — catches render crashes and shows friendly message ─────────
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { crashed: false, error: "" }; }
  static getDerivedStateFromError(e) { return { crashed: true, error: e?.message || String(e) }; }
  componentDidCatch(e, info) { console.error("ErrorBoundary caught:", e, info); }
  render() {
    if (this.state.crashed) {
      return React.createElement("div", {
        style: { padding: "24px", textAlign: "center" }
      },
        React.createElement("div", { style: { fontSize: "32px", marginBottom: "12px" } }, "⚠️"),
        React.createElement("div", { style: { fontSize: "14px", fontWeight: "600", color: "#333", marginBottom: "8px" } }, "잠깐 오류가 발생했어요"),
        React.createElement("div", { style: { fontSize: "11px", color: "#ccc", marginBottom: "8px", fontFamily: "monospace", padding: "8px", background: "#f5f5f5", borderRadius: "8px", wordBreak: "break-all", textAlign: "left" } }, this.state.error),
        React.createElement("div", { style: { fontSize: "13px", color: "#888", marginBottom: "16px" } }, "다시 시도해 주세요!"),
        React.createElement("button", {
          onClick: () => this.setState({ crashed: false, error: "" }),
          style: { padding: "10px 24px", borderRadius: "100px", background: "#1A3A6E", color: "#fff", border: "none", fontSize: "13px", fontWeight: "700", cursor: "pointer" }
        }, "🔄 다시 시도")
      );
    }
    return this.props.children;
  }
}

// ── TourSpotlight ─────────────────────────────────────────────────────────────
// Fixed overlay with a cutout over the highlighted card and a floating tooltip.
// Uses SVG clipPath for the spotlight effect so the card glows through naturally.
// ── TourFingerTap ─────────────────────────────────────────────────────────────
function TourFingerTap({ rect, onDone, delay = 0 }) {
  const [phase, setPhase] = useState("hidden");

  useEffect(() => {
    if (!rect) return;
    const t = [];
    t.push(setTimeout(() => setPhase("appear"),  delay));
    t.push(setTimeout(() => { setPhase("tap"); haptic.light(); }, delay + 500));
    t.push(setTimeout(() => setPhase("lift"),    delay + 750));
    t.push(setTimeout(() => setPhase("fade"),    delay + 1050));
    t.push(setTimeout(() => { setPhase("hidden"); onDone?.(); }, delay + 1300));
    return () => t.forEach(clearTimeout);
  }, [rect]);

  if (phase === "hidden" || !rect) return null;

  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const scale = phase === "tap" ? 0.8 : 1;
  const opacity = phase === "fade" ? 0 : phase === "appear" ? 1 : 1;
  const ty = phase === "tap" ? 5 : 0;

  return ReactDOM.createPortal(
    React.createElement("div", { style: { position: "fixed", zIndex: 1100, pointerEvents: "none", left: cx - 22, top: cy - 10, width: 44, height: 52, transform: `scale(${scale}) translateY(${ty}px)`, opacity, transition: phase === "tap" ? "transform 0.2s cubic-bezier(0.4,0,0.2,1), opacity 0.15s" : phase === "lift" ? "transform 0.28s cubic-bezier(0.34,1.3,0.64,1)" : phase === "fade" ? "opacity 0.3s cubic-bezier(0.4,0,0.2,1)" : "opacity 0.2s ease" } },
      phase === "tap" && React.createElement("div", { style: { position: "absolute", inset: -10, borderRadius: "50%", border: "2px solid rgba(255,255,255,0.55)", animation: "fingerRipple 0.38s ease-out forwards" } }),
      React.createElement("div", { style: { fontSize: 34, lineHeight: 1, userSelect: "none", filter: "drop-shadow(0 2px 6px rgba(0,0,0,0.3))" } }, "👆")
    ),
    document.body
  );
}

