function FontSizeToggle({ fontSize, setFontSize }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", handler);
    document.addEventListener("touchstart", handler);
    return () => { document.removeEventListener("mousedown", handler); document.removeEventListener("touchstart", handler); };
  }, []);
  return React.createElement("div", { ref, style: { position: "relative" } },
    React.createElement("button", {
      onClick: () => setOpen(o => !o),
      style: { width: "32px", height: "32px", borderRadius: "50%", background: fontSize !== "default" ? C.text : C.bgSoft, border: `1px solid ${fontSize !== "default" ? C.text : C.border}`, color: fontSize !== "default" ? "#fff" : C.textMid, fontSize: "12px", fontWeight: "700", cursor: "pointer", fontFamily: FONT, display: "flex", alignItems: "center", justifyContent: "center", transition: "all 0.15s" }
    }, "Aa"),
    open && React.createElement("div", {
      style: { position: "absolute", top: "38px", right: 0, background: C.bg, border: `1px solid ${C.border}`, borderRadius: "12px", padding: "6px", minWidth: "140px", boxShadow: "0 8px 24px rgba(0,0,0,0.12)", zIndex: 100, animation: "fadeIn 0.15s ease" }
    },
      React.createElement("div", { style: { fontSize: "10px", color: C.textLight, letterSpacing: "1.5px", textTransform: "uppercase", padding: "4px 10px 8px", fontWeight: "600" } }, "Text Size"),
      ...[["default","Default"],["large","Large"],["xlarge","X-Large"]].map(([id, label]) =>
        React.createElement("button", { key: id, onClick: () => { setFontSize(id); setOpen(false); },
          style: { width: "100%", padding: "9px 12px", borderRadius: "8px", background: fontSize === id ? C.bgSoft : "transparent", border: "none", cursor: "pointer", fontFamily: FONT, display: "flex", alignItems: "center", justifyContent: "space-between", transition: "background 0.1s" } },
          React.createElement("span", { style: { fontSize: "13px", fontWeight: fontSize === id ? "700" : "400", color: C.text } }, label),
          fontSize === id && React.createElement("span", { style: { color: C.text, fontSize: "14px" } }, "✓")
        )
      )
    )
  );
}

// ── Teacher Comments ──────────────────────────────────────────────────────────
function TeacherCommentBox({ responseId, existingComment, onSaved, transcript, question, studentName, skillLevel = "beginner" }) {
  const [text, setText] = useState(existingComment?.teacher_text || "");
  const [saving, setSaving] = useState(false);
  const [audioBlob, setAudioBlob] = useState(null);
  const [audioUrl, setAudioUrl] = useState(null); // never pre-load existing audio — avoids duplicate player
  const [editing, setEditing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [generated, setGenerated] = useState(false);
  const [voiceMode, setVoiceMode] = useState(false); // true = voice-only, hides textarea

  // Sync text if parent comment changes (e.g. first load)
  useEffect(() => {
    if (!editing) setText(existingComment?.teacher_text || "");
  }, [existingComment?.teacher_text]);

  const handleRecordDone = (blob) => {
    setAudioBlob(blob);
    setAudioUrl(URL.createObjectURL(blob));
  };
  const voiceRec = useRecorder(handleRecordDone);

  const handleGenerate = async () => {
    if (!transcript) return;
    setGenerating(true); setGenerated(false);
    try {
      const isAdvanced = skillLevel === "advanced";
      const isIntermediate = skillLevel === "intermediate";
      const feedbackLang = isAdvanced || isIntermediate ? "English" : "Korean 해요체";
      const depthGuidance = isAdvanced
        ? `- Go beyond grammar: flag unnatural phrasing, overly formal constructions, or anything a native speaker wouldn't say even if technically correct\n- Suggest more idiomatic or natural alternatives where relevant\n- This student is aiming for native-level fluency — be specific and honest, not just encouraging`
        : isIntermediate
        ? `- Explain the grammar rule clearly so they understand WHY, not just what to fix\n- Give a practical tip they can apply to similar situations\n- Be warm but substantive — intermediate students can handle more detail`
        : `- Use simple, everyday language — avoid complex grammar terminology\n- One correction only — the most important one\n- Heavy on encouragement — beginners need confidence above all`;
      const langInstruction = isAdvanced || isIntermediate
        ? `Write entirely in English — warm and personal, not formal. When showing corrections, write both the wrong and right versions in English.`
        : `Write entirely in Korean 해요체 — warm, personal, never stiff. When showing English corrections, write them in English.`;
      const systemPrompt = `You are ${TEACHER_DISPLAY_NAME} — a warm, encouraging English coach writing private feedback to a Korean adult student in the WAYVE community. This is a close-knit church and friends community. Your feedback should feel personal, warm, and genuinely helpful — not like a form letter.\n\nFEEDBACK STRUCTURE (always follow this order):\n1. ONE specific thing they did well — be concrete, reference their actual words\n2. ONE grammar correction only — the most important one. Show the wrong version and the right version clearly\n3. ONE natural English tip — a more native-sounding alternative or expression they could use\n4. A warm closing that makes them want to speak again\n\nLANGUAGE: ${feedbackLang}\n${langInstruction}\n\nDEPTH GUIDANCE (student level: ${skillLevel}):\n${depthGuidance}\n\nKeep it under 180 words total. Sound like a real teacher who knows this student, not an AI.`;
      const userPrompt = `Student: ${studentName || "학생"}\nQuestion asked: "${question || ""}"\nStudent's answer: "${transcript}"\n\nWrite warm, specific feedback following the structure. Be personal — reference their actual words where possible.`;
      const feedback = await geminiCallForFeedback(userPrompt, systemPrompt);
      setText(feedback); setGenerated(true);
    } catch(e) { console.error("AI feedback generation failed:", e); }
    setGenerating(false);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      let finalAudioUrl = existingComment?.audio_url || null; // keep old audio if no new recording
      if (audioBlob) {
        try {
          const commentMime = audioBlob.type || "audio/webm";
          const commentExt = commentMime.includes("mp4") ? "mp4" : commentMime.includes("ogg") ? "ogg" : "webm";
          const fn = `comment_${responseId}_${Date.now()}.${commentExt}`;
          const up = await fetch(`${SUPABASE_URL}/storage/v1/object/qod-audio/${fn}`, { method: "POST", headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${SUPABASE_KEY}`, "Content-Type": commentMime.split(";")[0] }, body: audioBlob });
          if (up.ok) finalAudioUrl = `${SUPABASE_URL}/storage/v1/object/public/qod-audio/${fn}`;
          else finalAudioUrl = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(audioBlob); });
        } catch(e) {}
      }
      // If audio-only mode, clear text; otherwise use text
      const finalText = voiceMode ? "" : text.trim();
      if (existingComment?.id) await db.update("qod_comments", `id=eq.${existingComment.id}`, { teacher_text: finalText, audio_url: finalAudioUrl, seen_at: null }).catch(() => {});
      else await db.insert("qod_comments", { response_id: responseId, teacher_text: finalText, audio_url: finalAudioUrl }).catch(() => {});
      onSaved && onSaved({ teacher_text: finalText, audio_url: finalAudioUrl });
      setEditing(false); setGenerated(false); setAudioBlob(null); setAudioUrl(null); setVoiceMode(false);
    } catch(e) {}
    setSaving(false);
  };

  const handleCancel = () => {
    setEditing(false); setGenerated(false);
    setText(existingComment?.teacher_text || "");
    setAudioBlob(null); setAudioUrl(null); setVoiceMode(false);
  };

  // ── Collapsed state — shows existing feedback or an "Add feedback" prompt ──
  if (!editing) {
    const hasText = existingComment?.teacher_text;
    const hasAudio = existingComment?.audio_url;
    const hasFeedback = hasText || hasAudio;

    return (
      <div style={{ background: hasFeedback ? C.goldBg : "transparent", border: `1px solid ${hasFeedback ? C.goldBorder : C.border}`, borderRadius: "10px", padding: hasFeedback ? "12px" : "0", marginTop: hasFeedback ? "8px" : "0" }}>
        {hasFeedback && (
          <>
            {/* Header with seen status */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "6px" }}>
              <div style={{ fontSize: "10px", fontWeight: "700", color: C.gold, letterSpacing: "2px", textTransform: "uppercase" }}>
                👨‍🏫 {TEACHER_DISPLAY_NAME}' Feedback
              </div>
              {existingComment.seen_at
                ? <span title={`Seen ${new Date(existingComment.seen_at).toLocaleString()}`} style={{ fontSize: "10px", fontWeight: "600", color: C.success, background: C.successBg, padding: "2px 8px", borderRadius: "100px" }}>👁 Seen</span>
                : <span style={{ fontSize: "10px", fontWeight: "600", color: C.textLight, background: C.bgSoft, padding: "2px 8px", borderRadius: "100px" }}>Unseen</span>
              }
            </div>
            {/* Feedback content */}
            {hasText && <div style={{ fontSize: "13px", color: C.text, lineHeight: 1.65, marginBottom: hasAudio ? "8px" : "6px" }}>{existingComment.teacher_text}</div>}
            {hasAudio && <div style={{ marginBottom: "8px" }}>{React.createElement(RichAudioPlayer, { src: existingComment.audio_url, label: "Voice feedback" })}</div>}
            {/* Edit button — clearly labeled as editing, not adding */}
            <button onClick={() => setEditing(true)} style={{ background: "transparent", border: `1px solid ${C.goldBorder}`, borderRadius: "6px", padding: "5px 12px", fontSize: "11px", fontWeight: "600", color: C.gold, cursor: "pointer", fontFamily: FONT }}>
              ✏️ Edit feedback
            </button>
          </>
        )}
        {!hasFeedback && (
          <button
            onClick={() => { setEditing(true); if (transcript) handleGenerate(); }}
            style={{ background: "transparent", border: `1px dashed ${C.border}`, borderRadius: "8px", padding: "7px 12px", fontSize: "12px", color: C.textMid, cursor: "pointer", fontFamily: FONT, width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: "6px" }}>
            ✨ Generate AI feedback for student
          </button>
        )}
      </div>
    );
  }

  // ── Expanded edit state ──
  return (
    <div style={{ background: C.goldBg, border: `1px solid ${C.goldBorder}`, borderRadius: "10px", padding: "12px", marginTop: "8px" }}>

      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "10px" }}>
        <div style={{ fontSize: "11px", fontWeight: "700", color: C.gold, letterSpacing: "1px", textTransform: "uppercase" }}>
          {existingComment?.teacher_text || existingComment?.audio_url ? "Edit Feedback" : "New Feedback"} · Private
        </div>
        {transcript && !voiceMode && (
          <button onClick={handleGenerate} disabled={generating} style={{ background: generating ? C.bgSoft : C.navy, border: "none", borderRadius: "100px", padding: "5px 12px", fontSize: "11px", fontWeight: "700", color: generating ? C.textMid : "#fff", cursor: generating ? "default" : "pointer", fontFamily: FONT, display: "flex", alignItems: "center", gap: "5px" }}>
            {generating
              ? React.createElement(React.Fragment, null, React.createElement(Spinner), React.createElement("span", { style: { marginLeft: "6px" } }, "생성 중…"))
              : React.createElement("span", null, generated ? "↺ 재생성" : "✨ AI 생성")}
          </button>
        )}
      </div>

      {/* Student transcript reference */}
      {transcript && (
        <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: "8px", padding: "8px 12px", marginBottom: "10px", fontSize: "12px", color: C.textMid, lineHeight: 1.6, fontStyle: "italic" }}>
          <span style={{ fontWeight: "700", fontStyle: "normal", color: C.textLight, fontSize: "10px", letterSpacing: "1px", textTransform: "uppercase" }}>Student said  </span>
          {`"${transcript.length > 140 ? transcript.slice(0, 140) + "…" : transcript}"`}
        </div>
      )}

      {/* Mode toggle — text vs voice only */}
      <div style={{ display: "flex", gap: "6px", marginBottom: "10px" }}>
        <button onClick={() => setVoiceMode(false)} style={{ flex: 1, padding: "6px", fontSize: "11px", fontWeight: "600", borderRadius: "6px", border: `1px solid ${!voiceMode ? C.goldBorder : C.border}`, background: !voiceMode ? C.goldBg : "transparent", color: !voiceMode ? C.gold : C.textMid, cursor: "pointer", fontFamily: FONT }}>✍️ Text</button>
        <button onClick={() => setVoiceMode(true)} style={{ flex: 1, padding: "6px", fontSize: "11px", fontWeight: "600", borderRadius: "6px", border: `1px solid ${voiceMode ? C.goldBorder : C.border}`, background: voiceMode ? C.goldBg : "transparent", color: voiceMode ? C.gold : C.textMid, cursor: "pointer", fontFamily: FONT }}>🎙 Voice only</button>
      </div>

      {/* Text area — hidden in voice mode */}
      {!voiceMode && (
        generating
          ? <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "10px", padding: "24px", color: C.textMid, fontSize: "13px" }}>{React.createElement(Spinner)} AI가 피드백을 작성하고 있어요…</div>
          : React.createElement(React.Fragment, null,
              generated && <div style={{ fontSize: "10px", fontWeight: "700", color: C.gold, letterSpacing: "1px", textTransform: "uppercase", marginBottom: "5px" }}>✨ AI 생성 — 수정 후 저장하세요</div>,
              <textarea value={text} onChange={e => setText(e.target.value)}
                placeholder={transcript ? "AI 생성 버튼을 누르거나 직접 작성하세요…" : "Leave feedback, encouragement, or a tip…"}
                style={{ width: "100%", padding: "9px 12px", border: `1px solid ${generated ? C.goldBorder : C.border}`, borderRadius: "8px", fontSize: "13px", fontFamily: FONT, outline: "none", resize: "none", minHeight: "120px", lineHeight: 1.7, background: C.bg, marginBottom: "8px", boxSizing: "border-box" }} />
            )
      )}

      {/* Voice recording — only show when no existing audio or recording a new one */}
      <div style={{ marginBottom: "10px" }}>
        {!voiceRec.isRec && !audioUrl && (
          <button onClick={voiceRec.start} style={{ background: "transparent", border: `1px solid ${C.border}`, borderRadius: "100px", padding: "6px 14px", fontSize: "12px", fontWeight: "600", color: C.textMid, cursor: "pointer", fontFamily: FONT }}>
            🎙 {voiceMode ? "Record voice feedback" : "Add voice comment (optional)"}
          </button>
        )}
        {voiceRec.isRec && (
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <div style={{ width: "8px", height: "8px", borderRadius: "50%", background: C.error, animation: "recPulse 1.5s ease-in-out infinite" }} />
            <span style={{ fontSize: "12px", color: C.error }}>{`Recording… ${voiceRec.time}s`}</span>
            <button onClick={voiceRec.stop} style={{ background: "transparent", border: `1px solid ${C.error}`, borderRadius: "100px", padding: "4px 12px", fontSize: "12px", color: C.error, cursor: "pointer", fontFamily: FONT }}>Stop</button>
          </div>
        )}
        {audioUrl && !voiceRec.isRec && (
          <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
            {React.createElement(RichAudioPlayer, { src: audioUrl, label: "New recording preview" })}
            <button onClick={() => { setAudioUrl(null); setAudioBlob(null); }} style={{ background: "transparent", border: "none", color: C.error, cursor: "pointer", fontSize: "18px", lineHeight: 1 }}>×</button>
          </div>
        )}
      </div>

      {/* Save / Cancel */}
      <div style={{ display: "flex", gap: "8px" }}>
        <button onClick={handleSave} disabled={saving || generating || (!text.trim() && !audioUrl && !existingComment?.audio_url)}
          style={{ flex: 1, padding: "9px", background: saving ? C.bgSoft : C.navy, border: "none", borderRadius: "8px", fontSize: "13px", fontWeight: "700", color: saving ? C.textMid : "#fff", cursor: saving ? "default" : "pointer", fontFamily: FONT, display: "flex", alignItems: "center", justifyContent: "center", gap: "6px" }}>
          {saving ? React.createElement(Spinner) : "저장 · Send to Student"}
        </button>
        <button onClick={handleCancel} style={{ padding: "9px 16px", background: "transparent", border: `1px solid ${C.border}`, borderRadius: "8px", fontSize: "13px", color: C.textMid, cursor: "pointer", fontFamily: FONT }}>Cancel</button>
      </div>
    </div>
  );
}


// Wrapper that pre-downloads full audio blob before playing
// Fixes Supabase range-request truncation on all browsers
function BlobAudioPlayer({ src, label, autoPlay = false }) {
  const [blobUrl, setBlobUrl] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!src) return;
    let revoke = null;
    setLoading(true);
    setError(false);
    fetch(src, { cache: "no-store" })
      .then(r => {
        if (!r.ok) throw new Error("fetch failed " + r.status);
        return r.blob();
      })
      .then(blob => {
        console.log("[BLOB] Downloaded:", blob.size, "bytes");
        const url = URL.createObjectURL(blob);
        revoke = url;
        setBlobUrl(url);
        setLoading(false);
      })
      .catch(e => {
        console.warn("[BLOB] Failed:", e.message, "— using direct URL");
        setBlobUrl(src);
        setLoading(false);
        setError(true);
      });
    return () => { if (revoke) URL.revokeObjectURL(revoke); };
  }, [src]);

  if (loading) return React.createElement("div", { style: { display: "flex", alignItems: "center", gap: "8px", padding: "12px 0", color: C.textLight, fontSize: "13px" } },
    React.createElement(Spinner), React.createElement("span", null, "오디오 불러오는 중…")
  );
  return React.createElement(RichAudioPlayer, { src: blobUrl, label, autoPlay });
}
